        /* sdd-asis-lifecycle:begin img_61_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        IsurcdSearch2('ISU_CD','COM_NM',315,155)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf32200.img_61_onclick' }); }
